schema:
{
  "type": "object",
  "properties": {
    "command": {
      "type": "string",
      "enum": [
        "view"
      ],
      "description": "Operation to perform. Only \"view\" is available."
    },
    "path": {
      "type": "string",
      "description": "Absolute path inside the memory directory, e.g. /memories/user_profile.md"
    }
  },
  "required": [
    "command",
    "path"
  ]
}
